package com.example.rokidkeyboardbridge;
public final class RestConversationReactionTest {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[] args){RestConversationReaction r=new RestConversationReaction();r.user("ありがとう、助かった",1000);ok(r.face(0,false,1200)==6,"gratitude smiles");r.mode(1,1300,false);ok(r.kind(1400)==1,"thinking doesn't erase acknowledgement");r.answer(FullBodyPoseCatalog.Kind.NEUTRAL,1500);ok(r.kind(1600)==1,"neutral response keeps meaningful user reaction");r.answer(FullBodyPoseCatalog.Kind.JOY,5000);ok(r.face(0,false,5100)==6&&!r.moving(5100),"slow answer refreshes face without restarting body");ok(r.age(5100)==4100,"same reaction clock not reset");ok(r.face(1,true,5100)==1,"manual kiss expression wins");r.clear();ok(r.face(0,false,5200)==0,"clear removes pending face");
 FullBodyPoseCatalog.Kind[] kinds={FullBodyPoseCatalog.Kind.THINK,FullBodyPoseCatalog.Kind.SURPRISE,FullBodyPoseCatalog.Kind.WORRY,FullBodyPoseCatalog.Kind.SAD};int[] faces={7,8,9,9};for(int i=0;i<kinds.length;i++){RestConversationReaction q=new RestConversationReaction();q.answer(kinds[i],10000);ok(q.face(0,false,11000)==faces[i],"semantic face "+kinds[i]);ok(q.kind(15000)==0,"bounded event lifetime");}
 for(String text:new String[]{"ありがとうの意味は？","彼女が可愛いと言った","かわいくない","引用したありがとうという言葉"}){RestConversationReaction q=new RestConversationReaction();q.user(text,1000);ok(q.kind(1100)==0,"no quote/negative trigger");}
 RestConversationReaction a=new RestConversationReaction();a.mode(1,1000,true);ok(a.kind(1100)==0,"local display operation doesn't act like thinking");a.touch(2000,1,false);ok(a.kind(2100)==5,"button acknowledgement");a.touch(2100,-1,false);ok(a.age(2200)==200,"hardware bounce debounce");a.touch(2400,-1,true);ok(a.kind(2500)==6&&a.direction()==-1,"swipe direction");
 EmbodiedScenePolicy p=new EmbodiedScenePolicy();p.user("寝たまま立膝にして",1000);ok(!p.restFacePinned(),"default automatic");p.user("キス顔にして",2000);ok(p.restFacePinned()&&p.restMotion(2100)==5,"explicit face pins without lowering knee");p.user("表情をおまかせにして",3000);ok(!p.restFacePinned()&&p.restMotion(3100)==5,"auto mode keeps knee");for(int action=14;action<=17;action++){String text=new String[]{"うれしい顔にして","考える顔にして","驚いた顔にして","心配そうな顔にして"}[action-14];p.user(text,action*1000);ok(p.restFace()==action-8&&p.restFacePinned(),"new explicit face");ok(RestAnimationIntent.action(text)==action,"new local parser");}
 float[] points=new float[17*33*2],base=new float[points.length];for(int row=0;row<=32;row++)for(int col=0;col<=16;col++){int i=(row*17+col)*2;points[i]=base[i]=512*col/16f;points[i+1]=base[i+1]=768*row/32f;}RestInteractionMotion.apply(points,16,32,512,768,255,110,1,0,1000,1);boolean changed=false;for(int row=0;row<=32;row++)for(int col=0;col<=16;col++){int i=(row*17+col)*2;if(points[i]!=base[i]||points[i+1]!=base[i+1]){changed=true;ok(768*row/32f<255,"hips and legs anchored");}}ok(changed,"event creates small torso motion");
 System.out.println("PASS "+n+" semantic rest reaction/priority/cooldown/pose/mesh checks");}
}
